// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address sender, uint256 amount) public {
        vm.assume(sender != address(0));
        amount = bound(amount, 0, type(uint128).max);

        uint256 old = c.getBalance(sender);

        vm.deal(sender, amount);
        vm.prank(sender);
        c.addToBalance{value: amount}();

        uint256 newBal = c.getBalance(sender);

        assertTrue(newBal == old + amount);
    }
}
